import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Equipment from './Equipment';
import EquipmentSearch from './EquipmentSearch';
import styled from 'styled-components';

const Container = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const EquipmentPage = () => {
  const [equipmentData, setEquipmentData] = useState([]);
  const [selection, setSelection] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const itemsPerPage = 20;

  const fetchData = async (searchTerm = '', category = 'all', minPrice = '', maxPrice = '') => {
    setLoading(true);
    try {
      const response = await axios.get('/api/equipment', {
        params: {
          page: currentPage,
          search: searchTerm,
          category,
          min_price: minPrice,
          max_price: maxPrice,
        },
      });
      setEquipmentData(response.data.equipment);
      setTotalPages(response.data.total_pages);
      setLoading(false);
    } catch (error) {
      setError('Failed to load data');
      setLoading(false);
    }
  };

  const fetchSelection = async () => {
    try {
      const response = await axios.get('/api/selection', {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      setSelection(response.data);
    } catch (error) {
      console.error('Error loading selections', error);
    }
  };

  useEffect(() => {
    fetchData();
    fetchSelection();
  }, [currentPage]);

  const addToSelection = async (equipment) => {
    try {
      await axios.post(
        '/api/selection',
        { equipment_id: equipment.id },
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );
      setSelection([...selection, equipment]);
    } catch (error) {
      console.error('Failed to add item to selection', error);
    }
  };

  const removeFromSelection = async (itemId) => {
    try {
      await axios.delete(`/api/selection/${itemId}`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      setSelection(selection.filter((item) => item.id !== itemId));
    } catch (error) {
      console.error('Failed to remove item from selection', error);
    }
  };

  const nextPage = () => {
    if (currentPage < totalPages) {
      setCurrentPage((prevPage) => prevPage + 1);
    }
  };

  const prevPage = () => {
    if (currentPage > 1) {
      setCurrentPage((prevPage) => prevPage - 1);
    }
  };

  const handleSearch = (searchTerm, category, minPrice, maxPrice) => {
    setCurrentPage(1);
    fetchData(searchTerm, category, minPrice, maxPrice);
  };

  if (loading) return <p>Loading...</p>;
  if (error) return <p>{error}</p>;

  return (
    <Container>
      <EquipmentSearch onSearch={handleSearch} />
      <Equipment equipment={equipmentData} onAddToSelection={addToSelection} />

      <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
        <button onClick={prevPage} disabled={currentPage === 1}>Previous</button>
        <span style={{ margin: '0 10px' }}>Page {currentPage} of {totalPages}</span>
        <button onClick={nextPage} disabled={currentPage === totalPages}>Next</button>
      </div>

      <div className="selection-sidebar">
        <h2>Your Selection</h2>
        <ul>
          {selection.map((item) => (
            <li key={item.id}>
              {item.name} - ${item.price}
              <button onClick={() => removeFromSelection(item.id)}>Remove</button>
            </li>
          ))}
        </ul>
        <div>Total: ${selection.reduce((sum, item) => sum + item.price, 0)}</div>
      </div>
    </Container>
  );
};

export default EquipmentPage;
